const conf = $('Configuración').first().json;
const body = $input.first().json;
const sumario = body.data && typeof body.data === 'object' ? body.data.sumario : null;
// Sunday, a holiday or not published yet: there is no BOE for that date.
if (!sumario) return [];

const lista = (x) => (Array.isArray(x) ? x : x ? [x] : []);
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const escapar = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Each term matches at the start of a word and without accents: "tributari" finds "tributaria", but "iva" does not match "definitiva".
const patron = (terms) => {
  const l = lista(terms).filter(Boolean);
  return l.length ? new RegExp(l.map((t) => '\\b' + escapar(norm(t))).join('|')) : null;
};
const epigrafes = patron(conf.epigrafes);
const palabras = patron(conf.palabras);
const excluir = patron(conf.excluir);
const secciones = lista(conf.secciones).map(String);

const salida = [];
for (const diario of lista(sumario.diario)) {
  for (const sec of lista(diario.seccion)) {
    if (!secciones.includes(String(sec.codigo))) continue;
    for (const dep of lista(sec.departamento)) {
      const grupos = lista(dep.epigrafe).map((e) => [e.nombre, e.item]).concat([['', dep.item]]);
      for (const [epigrafe, items] of grupos) {
        for (const it of lista(items)) {
          const titulo = norm(it.titulo);
          const encaja = (epigrafes && epigrafes.test(norm(epigrafe))) || (palabras && palabras.test(titulo));
          if (!encaja || (excluir && excluir.test(titulo))) continue;
          salida.push({
            json: {
              fecha: sumario.metadatos.fecha_publicacion,
              seccion: sec.nombre,
              departamento: dep.nombre,
              epigrafe: epigrafe || '',
              titulo: it.titulo,
              identificador: it.identificador,
              url_html: it.url_html,
              url_pdf: typeof it.url_pdf === 'object' ? it.url_pdf.texto : it.url_pdf,
              url_xml: it.url_xml,
            },
          });
        }
      }
    }
  }
}
return salida;

const conf = $('Configuración').first().json;
const disposiciones = $input.all().map(({ json: d }) => ({
  id: d.identificador,
  seccion: d.seccion,
  departamento: d.departamento,
  epigrafe: d.epigrafe,
  titulo: d.titulo,
}));
const instrucciones = [
  'Ayudas a una gestoría española (asesoría fiscal, laboral y contable de autónomos y pymes) a revisar el BOE del día.',
  'Lo que más mira es lo laboral: el Estatuto de los Trabajadores, los convenios colectivos y sus tablas salariales, y la cotización a la Seguridad Social.',
  'Recibes una lista JSON de disposiciones con id, sección, departamento, epígrafe y título. Para cada una devuelve:',
  '- id: el mismo que recibes.',
  '- resumen: qué hace, en una frase llana de 25 palabras como mucho, sin repetir el número de la norma ni su fecha.',
  '- afecta_a: a quién afecta, en 8 palabras como mucho. Por ejemplo: «autónomos en módulos», «empresas con trabajadores», «solo la plantilla de Airbus».',
  '- relevancia para la gestoría:',
  '  «alta»: lo laboral de alcance general (Estatuto de los Trabajadores, contratos, jornada, despido, salario mínimo, fiestas laborales), la cotización a la Seguridad Social y las prestaciones que tramita una gestoría, los convenios colectivos de sector y sus tablas salariales, y los cambios en impuestos, plazos, modelos u obligaciones de autónomos y pymes en general.',
  '  «media»: lo que afecta solo a un sector, un colectivo o un territorio concreto sin ser un convenio de sector, obligaciones específicas como Intrastat, y la prevención de riesgos laborales.',
  '  «baja»: el convenio o las tablas de una sola empresa (su nombre lleva SA, SL, SAU o similar), la organización interna o la contabilidad de la Administración, las elecciones y los casos particulares, como un recurso o un registro concreto.',
  'Trabaja solo con el título: no inventes cifras, plazos ni fechas que no aparezcan en él. Devuelve todas las disposiciones, en el mismo orden.',
].join('\n');
const esquema = {
  type: 'object',
  properties: {
    disposiciones: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          resumen: { type: 'string' },
          afecta_a: { type: 'string' },
          relevancia: { type: 'string', enum: ['alta', 'media', 'baja'] },
        },
        required: ['id', 'resumen', 'afecta_a', 'relevancia'],
        additionalProperties: false,
      },
    },
  },
  required: ['disposiciones'],
  additionalProperties: false,
};
return [
  {
    json: {
      peticion: {
        model: conf.modelo_groq || 'openai/gpt-oss-120b',
        messages: [
          { role: 'system', content: instrucciones },
          { role: 'user', content: JSON.stringify(disposiciones) },
        ],
        response_format: { type: 'json_schema', json_schema: { name: 'resumen_boe', strict: true, schema: esquema } },
        reasoning_effort: 'low',
        temperature: 0.2,
        max_completion_tokens: 4000,
      },
    },
  },
];

const items = $('Filtrar').all().map((i) => i.json);
const f = items[0].fecha;
const fecha = `${f.slice(6, 8)}/${f.slice(4, 6)}/${f.slice(0, 4)}`;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const asunto = `BOE del ${fecha}: ${items.length} ${items.length === 1 ? 'disposición' : 'disposiciones'} para tu gestoría`;
const sumario = `https://www.boe.es/boe/dias/${f.slice(0, 4)}/${f.slice(4, 6)}/${f.slice(6, 8)}/`;

// Groq's answer, by BOE id. If Groq failed, the summary goes out with the titles alone.
let notas = {};
try {
  const r = JSON.parse($input.first().json.choices[0].message.content);
  for (const n of r.disposiciones) notas[n.id] = n;
} catch (e) {
  notas = {};
}
const conIA = items.some((d) => notas[d.identificador]);
const grupos = [
  ['alta', 'Importante'],
  ['media', 'Para revisar'],
  ['baja', 'Menos relevante'],
];
const nivel = (d) => (notas[d.identificador] ? notas[d.identificador].relevancia : 'media');
const ordenadas = conIA ? grupos.flatMap(([g]) => items.filter((d) => nivel(d) === g)) : items;
const norma = (d) => d.titulo.split(',')[0];

const texto = ordenadas
  .map((d) => {
    const n = notas[d.identificador];
    return n
      ? `- [${n.relevancia}] ${d.epigrafe || d.departamento}: ${n.resumen} (afecta a: ${n.afecta_a})\n  ${norma(d)}: ${d.url_html}`
      : `- ${d.epigrafe || d.departamento}: ${d.titulo}\n  ${d.url_html}`;
  })
  .join('\n');

const bloqueHtml = (d) => {
  const n = notas[d.identificador];
  return n
    ? `<li><strong>${esc(d.epigrafe || d.departamento)}</strong><br>${esc(n.resumen)}<br>Afecta a: ${esc(n.afecta_a)}<br><a href="${esc(d.url_html)}">${esc(norma(d))}</a></li>`
    : `<li><strong>${esc(d.epigrafe || d.departamento)}</strong><br>${esc(d.titulo)}<br><a href="${esc(d.url_html)}">Leer en el BOE</a></li>`;
};
const html =
  `<h2>${esc(asunto)}</h2>` +
  (conIA
    ? grupos
        .map(([g, t]) => [t, ordenadas.filter((d) => nivel(d) === g)])
        .filter(([, l]) => l.length)
        .map(([t, l]) => `<h3>${t}</h3><ul>${l.map(bloqueHtml).join('')}</ul>`)
        .join('') + '<p><em>Resúmenes hechos con IA a partir del título. Comprueba siempre el texto en el BOE.</em></p>'
    : `<ul>${ordenadas.map(bloqueHtml).join('')}</ul>`);

const bloqueTg = (d) => {
  const n = notas[d.identificador];
  return n
    ? `<b>${esc(d.epigrafe || d.departamento)}</b>\n${esc(n.resumen)}\nAfecta a: ${esc(n.afecta_a)}\n<a href="${esc(d.url_html)}">${esc(norma(d))}</a>`
    : `<b>${esc(d.epigrafe || d.departamento)}</b>\n${esc(d.titulo)}\n<a href="${esc(d.url_html)}">Leer en el BOE</a>`;
};
const pie = conIA
  ? '<i>Resúmenes hechos con IA a partir del título. Comprueba siempre el texto en el BOE.</i>'
  : '<i>Hoy sin resúmenes: la llamada a Groq falló.</i>';
// Telegram caps a message at 4096 characters: what does not fit stays behind a link to the day's summary.
let telegram = `<b>${esc(asunto)}</b>`;
let n = 0;
let grupo = null;
while (n < ordenadas.length) {
  const d = ordenadas[n];
  const cabecera = conIA && nivel(d) !== grupo ? `\n\n<u>${grupos.find(([g]) => g === nivel(d))[1]}</u>` : '';
  const siguiente = telegram + cabecera + '\n\n' + bloqueTg(d);
  if (siguiente.length > 3800) break;
  telegram = siguiente;
  grupo = nivel(d);
  n++;
}
if (n < ordenadas.length) telegram += `\n\n…y ${ordenadas.length - n} más en <a href="${sumario}">el sumario del BOE</a>.`;
telegram += '\n\n' + pie;
return [{ json: { asunto, total: items.length, con_ia: conIA, texto, html, telegram } }];
